      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00886",
          "explanation": "针对患者疲劳、焦虑和记忆负担，将复杂术前问题压缩成四句可直接询问的话。",
          "quote": "我帮您再精炼成4句"
        }
      ],
      "completion": "complete",
      "explanation": "沟通明确适配患者疲劳和害怕麻醉的状态，以短句和编号降低认知负担，同时维持风险优先级。",
      "ho_id": "HO3",
